        if not self._isCanShowTuJian then
            GameUtils.Toast(localize("敬请期待"))
            return
        end
        self._isCloseScene = true
        KCookie.Set("IsNeedRefreshInteraction", 1)
        UIModule.OpenDialog({id = Constants.UITypeIds.IllustratedHandbookRoleDetailsDialog, parameters = {roleId = self._curRoleId, isHidePlotBtn = true }}, {
            {id = Constants.UITypeIds.UIMainInteractionDialog}
        })
    end)

