function UIMainInteractionDialog:ClearClickNode()
    if isNull(self._roleAni) then
        return
    end
    local vo = PhoneUtils.GetPhoneRoleVisitingVo(self._curRoleId)
    if not vo then
        return
    end

    --self:FillClickNode(self._roleAni.transform:Find(PhoneUtils.GetRoleNodePath(vo.ear)), ClickRoleType.Ears, true)
