    --self:FillClickNode(self._roleAni.transform:Find(PhoneUtils.GetRoleNodePath(vo.armLeft)), ClickRoleType.Arms, true)
    --self:FillClickNode(self._roleAni.transform:Find(PhoneUtils.GetRoleNodePath(vo.armRight)), ClickRoleType.Arms, true)
    self:FillClickNode(self._roleAni.transform:Find(PhoneUtils.GetRoleNodePath(vo.body)), ClickRoleType.Chest, true)

    local boxCollider = self._roleAni.gameObject:GetComponent(typeof(CS.UnityEngine.BoxCollider))
    if boxCollider then
        boxCollider.enabled = true
    end
end

function UIMainInteractionDialog:FillClickNode(go, type, isClear)
    if isNull(go) then
        return
    end
    local boxCollider = go.gameObject:GetComponent(typeof(CS.UnityEngine.BoxCollider))
    if boxCollider then
        boxCollider.enabled = true
    end

    if isClear then
        if boxCollider then
            boxCollider.enabled = false
        end
        return
    end 

    self:SetRoleClick(go, type)
end

function UIMainInteractionDialog:SetRoleClick(go, type)
    if isNull(go) then
        return
    end

    local quickTap = KTool.GetOrAddComponent(go.gameObject, typeof(CS.HedgehogTeam.EasyTouch.QuickTap))
    if not isNull(quickTap) then
        quickTap.onTap:RemoveAllListeners()
        quickTap.onTap:AddListener(Bind(self, self.OnBtnRole, type))
    end
end

function UIMainInteractionDialog:OnBtnRole(type)
    if self._isTouch then
        return
    end

    --local id = PhoneUtils.GetOrderRoleTalkRandomId(self._curRoleId, type)
    --local vo = PhoneUtils.GetOrderRoleTalkVo(id)
    --if not vo then
    --    return
    --end
    self._isTouch = true
    --CfUtils.FillText(self.TextContent, vo.text)
    
    local num = math.random(2)
    local triggerNum = 0
    if checkNumber(type) == ClickRoleType.Face then
        triggerNum = FaceTriggers[num]
    else
        triggerNum = BodyTriggers[num]
    end
    self._roleAni:SetInteger("trigger", checkNumber(triggerNum))
end

function UIMainInteractionDialog:OnUpdate()
    if self._isTouch then
        local animatorInfo = self._roleAni:GetCurrentAnimatorStateInfo(0)
        if isNull(animatorInfo) then
            return
        end
        if not animatorInfo:IsName("home_e_initial") and not animatorInfo:IsName("home_d_initial") 
         and not animatorInfo:IsName("home_c_initial") and not animatorInfo:IsName("home_b_initial") 
          and not animatorInfo:IsName("home_a_initial") then 
            self._roleAni:SetInteger("trigger", 0)
            self._isTouch = false
            self._isBeginAni = true
        end
    end

    --[[
    if self._isBeginAni then
        local animatorInfo = self._roleAni:GetCurrentAnimatorStateInfo(0)
        if not isNull(animatorInfo) then
            if animatorInfo:IsName("home_e_initial") then 
                self._isBeginAni = false
            end
        end
    end
    ]]
end

--按钮
function UIMainInteractionDialog:FillBtnsInfo()
    local t = CfUtils.Split(self._curRoleVo.layoutBtn)
    if not t then
        return
    end
    --table.insert(t, 2)
    for k, v in pairs(t) do
        --好感度信息
        if checkNumber(v) == 1 then
            self:FillFavorabilityInfo()
        else
            local go = self["Btn"..v]
            self:FillBtnInfo(go, v)
            KTool.SetActive(go, true)
        end
    end
end

function UIMainInteractionDialog:FillFavorabilityInfo()
    CfUtils.SetActive(self.Slider, true)
    CfUtils.SetActive(self.ImgFavorability, true)
    local level, exp = PhoneUtils.GetCatFavorabilityLevelAndCurExp(self._curRoleId)
    CfUtils.FillText(self.TxtNum2, level)
    self.Slider.value = checkNumber(exp) / PhoneUtils.GetLikabilityLevelUpAllExp(level)
end

function UIMainInteractionDialog:FillBtnInfo(go, id)
    id = checkNumber(id)
    if not go then
        return
    end
    if id == BtnIds.Id1 then
        SetButtonAction(go, Bind(self, self.OnBtnGiveGift))
    elseif id == BtnIds.Id2 then
        SetButtonAction(go, Bind(self, self.OnBtnChange))
    elseif id == BtnIds.Id3 then
        GameUtils.RefeshSystemToggleId(go, Constants.SystemToggleIds.Id13)
        local curPassNum, allNum = QuestConfMgr:GetInstance():GetRoleStoryOverFinaleIdNum(self._curRoleId)
        CfUtils.FillText(self.TxtNumber, string.format("<color=#ffffff><size=54>%d</color></size>/%d", curPassNum, allNum))
        SetButtonAction(go, Bind(self, self.OnBtnFilm))
    elseif id == BtnIds.Id4 then
        GameUtils.RefeshSystemToggleId(go, Constants.SystemToggleIds.Id27)
        SetButtonAction(go, Bind(self, self.OnBtnCooking))
    elseif id == BtnIds.Id5 then
        GameUtils.RefeshSystemToggleId(go, Constants.SystemToggleIds.Id26)
        SetButtonAction(go, Bind(self, self.OnBtnOrder))

        local remainNum = PhoneUtils.GetMaxOrderTimes() - phoneComp:GetCurOrderTimes()
        if remainNum < 0 then 
            remainNum = 0
        end

        CfUtils.FillText(go.transform:Find("TextNumber"), (remainNum).."/"..PhoneUtils.GetMaxOrderTimes())
    elseif id == BtnIds.Id6 then
        GameUtils.RefeshSystemToggleId(go, Constants.SystemToggleIds.Id26)
        --self._isCanShowTuJian = true
        SetButtonAction(go, Bind(self, self.OnBtnInvite))
        local roleOrderNum = PhoneUtils.GetRoleOrderNum(self._curRoleId)
        KTool.SetActive(go.transform:Find("Area"), roleOrderNum <= 0)

        local status = 1
        local roleOrderNum =  PhoneUtils.GetRoleOrderNum(self._curRoleId)
        if roleOrderNum < 1 then
            status = 2
        elseif phoneComp:GetCurOrderTimes() >= PhoneUtils.GetMaxOrderTimes() then
            status = 2
        end
        CfUtils.SetUISwitchImage(go.transform:Find("ImgIcon"), status)
        KTool.SetActive(go.transform:Find("ImgIcon/ImgStatus"), status == 2)
    end
end


function UIMainInteractionDialog:FillRoleInfo()
    if self._curRoleVo then
        CfUtils.FillText(self.TxtName1, self._curRoleVo.name)
        CfUtils.FillText(self.TxtName2, self._curRoleVo.catName)
        CfUtils.FillText(self.TxtNum, PhoneUtils.GetCatFavorabilityLevel(self._curRoleId))  
        CfUtils.FillText(self.TxtLeftName, self._curRoleVo.name)

        CfUtils.SetActive(self.TitleGroup.transform:Find("ImgEnglishName"), true)

        local roleVo = CardConfMgr:GetInstance():GetRolesByCharacterType(self._curRoleId)
        if roleVo then
            CfUtils.FillText(self.TitleGroup.transform:Find("ImgEnglishName/TxtName3"), roleVo.englishName)
        end
    end
end

--对话信息刷新
function UIMainInteractionDialog:FillTalkInfo()
    local data = RolesShowMgr:GetInstance():GetRoleInstance(self._curRoleId)
    if isNull(data) then
        return
    end
    local go = data._modelGo
    if isNull(go) then
        return
    end
    if go then
        local roleVoiceVo = RoleVoiceMgr:GetInstance():PlayHomeTouchVoiceByRoleId(self._curRoleId, go)
        if roleVoiceVo then
            CfUtils.FillText(self.TxtContent, roleVoiceVo:GetDesk())
        end
    end
end

