--邀请
function UIMainInteractionDialog:OnBtnInvite()
    if checkNumber(self._curRoleId) == 0 then
        return
    end
    local roleOrderNum =  PhoneUtils.GetRoleOrderNum(self._curRoleId)
    if roleOrderNum < 1 then
        GameUtils.Toast(localize("该角色今日邀请次数已用完"))
        return
    elseif phoneComp:GetCurOrderTimes() >= PhoneUtils.GetMaxOrderTimes() then
        GameUtils.Toast(localize("今日邀请次数已用完"))
        return
    end

    self._notIsBack = true
    cs_coroutine.start(function()
        local roleVoiceVo = RoleVoiceMgr:GetInstance():PlayRoleDating(self._curRoleId, 18)
        CS.Engine.UI.UIRaycastBlocker.Instance:AddCondition("UIMainInteractionDialogOnBtnInvite")
        CfUtils.FillText(self.TxtContent, roleVoiceVo:GetDesk())
        coroutine.yield(Yielders.GetWaitForSeconds(1))
        KTool.SetActive(self.Root.transform:Find("DialogueFrameNode"), false)
        UIModule.OpenDialog({ id = Constants.UITypeIds.UIMainInteractionOrderDialog, parameters = {staticRoleId = self._curRoleId, specialRoleId = 108}}, {
            {id = Constants.UITypeIds.UIMainInteractionDialog}
        })
        CS.Engine.UI.UIRaycastBlocker.Instance:RemoveCondition("UIMainInteractionDialogOnBtnInvite")
        KCookie.Set("IsNeedRefreshInteraction", 1)
    end)
end

--料理
function UIMainInteractionDialog:OnBtnCooking()
    if checkNumber(self._curRoleId) == 0 then
        return
    end
    cookingComp:CookingHomeReq(function()
        self._notIsBack = true
        UIModule.OpenDialog({ id = Constants.UITypeIds.UIMainInteractionCookingMenuDialog, parameters = {}}, {
            {id = Constants.UITypeIds.UIMainInteractionDialog}
        })
    end)
end

