function UIMainInteractionDialog:OnInitialize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        RolesShowMgr:GetInstance():ClearCoffeeLoaderAndGo()

        KCookie.Set(Constants.IsBeginInteractive, 1)
        local argument = self.controller.Argument.parameters
        if not argument then
            return
        end
        Events.Broadcast(Constants.EventNames.UIMainHomeSceneFocusShowEventName, true)

        self._behaviourAction = KTool.GetOrAddComponent(self.controller.gameObject, typeof(BehaviourAction))
        self._behaviourAction.UpdateAction = function()
            self:OnUpdate()
        end

        Events.Broadcast(Constants.EventNames.MainHomeScrollActive, {isTrue = false})

        self._curRoleId = checkNumber(argument.roleId)
        self._curPosId = checkNumber(argument.posId)

        if self._curRoleId == 0 then
            return
        end
        if checkNumber(KCookie.Get("IsNeedRefreshInteraction")) == 1 then
            Events.Broadcast(Constants.EventNames.MainHomeRoleActive, {isShow = true, roleId = self._curRoleId})
        end
        Events.Broadcast(Constants.EventNames.MainHomeRoleActivity, { isActivity = false})

        self._curRoleVo = CfUtils.GetCfVo(AutoIds.IdSetting1810, "RoleShowVo", self._curRoleId)


        if checkNumber(KCookie.Get(Constants.IsOpnePageing)) == 1 or checkNumber(KCookie.Get("IsNeedRefreshInteraction")) == 1 then
            if checkNumber(KCookie.Get("IsNeedRefreshInteraction")) == 1 then
                KCookie.Set("IsNeedRefreshInteraction", 0)
            end

            cs_coroutine.start(function()
                KTool.SetActive(self.Root, false)
                
                coroutine.yield(RolesShowMgr:GetInstance():SetCameraActivity(true, self._curRoleVo.roleCamera))
                KTool.SetActive(self.Root, true)
                CS.UINavigationBarRoot.Instance:SetActive(true)
            end)
        else
            CS.UINavigationBarRoot.Instance:SetActive(true)
        end

        local isFinishRoleStoryReq = false
        local isFinishRoleReq = false
        --初始化角色剧情
        --local roleStoryComp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.RoleStoryQuestComponent)
        --roleStoryComp:EnterQuestReq(function()
            isFinishRoleStoryReq = true
        --end)

        local phoneComp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.PhoneComponent)
        phoneComp:EnterPhoneHomeReq(function()
            isFinishRoleReq = true
        end)

        local roleData = RolesShowMgr:GetInstance():GetRoleInstance(self._curRoleId)
        if isNull(roleData) then
            return
        end

        local go = roleData._modelGo
        if isNull(go) then
            return
        end
        self._roleAni = KTool.GetOrAddComponent(go, typeof(Animator))
        if self._curRoleId ~= 108 then
            local path = RolesShowMgr:GetInstance():GetHomeIdleControllerPath(self._curRoleId)
            self._loader = ResourceModule.LoadBundleSync(path)
            if self._loader.IsSuccess then
                local animCtrl = CS.UnityEngine.GameObject.Instantiate(self._loader.ResultObject)
                self._roleAni.runtimeAnimatorController = animCtrl
            else
                self._loader:Release()
                self._loader = nil
            end

            self._roleAni:SetInteger("idle", roleData:GetAnimatorNumByPosId(roleData._posId))
        end

        while (not isFinishRoleStoryReq or not isFinishRoleReq) do
            coroutine.yield()
        end

        self:FillSelf()
    end))
    return coWait
end

function UIMainInteractionDialog:OnHide()
    ---@type Engine.Lib.CoWait
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        local roleData = RolesShowMgr:GetInstance():GetRoleInstance(self._curRoleId)
        if isNull(roleData) then
            return
        end

        local go = roleData._modelGo
        if isNull(go) then
            return
        end

        self._roleAni = KTool.GetOrAddComponent(go, typeof(Animator))
        if self._curRoleId ~= 108 then
            local path = RolesShowMgr:GetInstance():GetHomeOriginControllerPath(self._curRoleId)
            local loader = RolesShowMgr:GetInstance():GetTimeLineLoader(path)

            if loader then
                local animCtrl = CS.UnityEngine.GameObject.Instantiate(loader.ResultObject)
                self._roleAni.runtimeAnimatorController = animCtrl
            end

            self._roleAni:SetInteger("idle", roleData:GetAnimatorNumByPosId(roleData._posId))
        end


        if not self._notIsBack then
            KTool.SetActive(self.Root, false)
            CS.UINavigationBarRoot.Instance:SetActive(false)

            RolesShowMgr:GetInstance():SetMainHomeCameraActivity(true)
            coroutine.yield(RolesShowMgr:GetInstance():SetCameraActivity(false, self._curRoleVo.roleCamera))
            CS.UINavigationBarRoot.Instance:SetActive(true)
            CfUtils.SetTopCommonActive(false, true)
        end
    end))
    return coWait
end

function UIMainInteractionDialog:OnFinalize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        if self._loader then
            self._loader:Release(true)
        end
        if self._isCloseScene then
           --Events.Broadcast(Constants.EventNames.UIMainHomeSceneFocusShowEventName, false)
           --Events.Broadcast(Constants.EventNames.MainHomeRoleActive, { isShow = false })
        end
        self:ClearClickNode()
        if not isNull(self._behaviourAction) then
            self._behaviourAction.UpdateAction = nil
        end
        Events.RemoveListener(Constants.EventNames.ClickMainHomeRole, self._clickMainHomeRoleHandler)
        self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
        self:Delete()
        self = nil --lua层的gc需要
    end))
    return coWait
end

return UIMainInteractionDialog
